<p>\u062F\u0631 \u0627\u06CC\u0646 \u0645\u062B\u0627\u0644\u060C \u0635\u0627\u062D\u0628 \u0639\u0637\u0627\u0631\u06CC \u062A\u0627\u0632\u0647 \u0628\u0639\u062F \u0627\u0632 \u062F\u06CC\u062F\u0646 \u0646\u0645\u0648\u062F\u0627\u0631 \u0645\u062A\u0648\u062C\u0647 \u0634\u062F \u06A9\u0647 \u0641\u0631\u0648\u0634 \u062A\u0627\u0628\u0633\u062A\u0627\u0646 \u0647\u0631 \u0633\u0627\u0644 \u0627\u0641\u062A \u0645\u06CC\u200C\u06A9\u0646\u062F \u0648 \u0645\u0647\u0631 \u062F\u0648\u0628\u0627\u0631\u0647 \u0627\u0648\u062C \u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F. \u062D\u0627\u0644\u0627 \u0645\u06CC\u200C\u062F\u0627\u0646\u062F \u062E\u0631\u06CC\u062F \u0639\u0645\u062F\u0647 \u0631\u0627 \u06A9\u06CC \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u062F.</p>
