<p>\u0642\u06CC\u0645\u062A\u200C\u06AF\u0630\u0627\u0631\u06CC \u0647\u0646\u0631 \u0627\u0633\u062A\u060C \u0627\u0645\u0627 \u0647\u0646\u0631\u06CC \u06A9\u0647 \u0628\u0627 \u0639\u062F\u062F \u062E\u06CC\u0644\u06CC \u0628\u0647\u062A\u0631 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0641\u0631\u0648\u0634\u06AF\u0627\u0647\u200C\u0647\u0627\u06CC \u0632\u0646\u062C\u06CC\u0631\u0647\u200C\u0627\u06CC \u0647\u0631 \u0647\u0641\u062A\u0647 \u0647\u0645\u06CC\u0646 \u06A9\u0627\u0631 \u0631\u0627 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F\u061B \u0645\u063A\u0627\u0632\u0647\u0654 \u0645\u062D\u0644\u0647 \u0647\u0645 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F.</p>
