<p>\u0645\u0642\u0627\u06CC\u0633\u0647\u0654 \u0645\u0646\u0638\u0645 \u0634\u0639\u0628\u0647\u200C\u0647\u0627\u060C \u0628\u0647\u200C\u062C\u0627\u06CC \u0645\u0642\u0635\u0631 \u067E\u06CC\u062F\u0627 \u06A9\u0631\u062F\u0646\u060C \u0631\u0627\u0647 \u0628\u0647\u062A\u0631 \u06A9\u0627\u0631 \u06A9\u0631\u062F\u0646 \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F\u061B \u0648 \u0647\u0631 \u0634\u0639\u0628\u0647 \u0631\u0627 \u0628\u0647 \u0633\u0637\u062D \u0628\u0647\u062A\u0631\u06CC\u0646 \u0634\u0639\u0628\u0647 \u0646\u0632\u062F\u06CC\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u062F.</p>
