<h2>\u0647\u0632\u06CC\u0646\u0647\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0631\u0648\u06CC \u0641\u0627\u06A9\u062A\u0648\u0631 \u0646\u06CC\u0633\u062A</h2>
