<li><strong>\u062C\u0645\u0639\u200C\u0622\u0648\u0631\u06CC</strong>: \u0641\u0631\u0648\u0634 \u0647\u0631 \u06A9\u062F \u0648 \u0647\u0631 \u0644\u06CC\u0646\u06A9\u060C \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0647\u0632\u06CC\u0646\u0647\u0654 \u0647\u0645\u0627\u0646 \u062A\u0628\u0644\u06CC\u063A \u062B\u0628\u062A \u0645\u06CC\u200C\u0634\u0648\u062F.</li>
